"""A small, standalone TOML reader and the catalogue's deterministic writer.

The parser keeps table entries in their input order, including repeated keys.
That lets the schema distinguish repeated known fields from ignored metadata.
"""
import re
from common import rust_char


class TomlError(Exception):
    pass


class Table:
    def __init__(self):
        self.entries = []

    def get(self, key):
        for k, value in reversed(self.entries):
            if k == key:
                return value
        return None

    def put(self, key, value):
        self.entries.append((key, value))


class DateValue:
    def __init__(self, value):
        self.value = value


class Parser:
    def __init__(self, text):
        self.text = text
        self.i = 1 if text.startswith('\ufeff') else 0
        self.n = len(text)
        self.root = Table()
        self.current = self.root
        self.defined = set()

    def line(self, position=None):
        return self.text.count('\n', 0, self.i if position is None else position) + 1

    def error(self, message, position=None):
        raise TomlError('%s at line %s' % (message, self.line(position)))

    def char(self):
        return self.text[self.i] if self.i < self.n else ''

    def newline(self):
        if self.char() == '\n':
            self.i += 1
            return True
        if self.text.startswith('\r\n', self.i):
            self.i += 2
            return True
        return False

    def space(self, newlines=False):
        while self.i < self.n:
            c = self.char()
            if c in ' \t':
                self.i += 1
            elif c == '#':
                while self.i < self.n and self.char() not in '\r\n':
                    self.i += 1
                if not newlines:
                    break
            elif newlines and self.newline():
                pass
            else:
                break

    def token_name(self):
        c = self.char()
        names = {'=': 'an equals', '[': 'a left bracket', ']': 'a right bracket',
                 '{': 'a left brace', '}': 'a right brace', '.': 'a period',
                 ',': 'a comma', '\n': 'a newline', '"': 'a string', "'": 'a string'}
        if not c:
            return 'eof'
        if self.text.startswith('\r\n', self.i):
            return 'a newline'
        if c in names:
            return names[c]
        if c.isascii() and (c.isalnum() or c in '_-+'):
            return 'an identifier'
        self.error('unexpected character found: `%s`' % rust_char(c))

    def expect(self, char, name):
        if self.char() != char:
            self.error('expected %s, found %s' % (name, self.token_name()))
        self.i += 1

    def string(self):
        quote = self.char()
        start = self.i
        multi = self.text.startswith(quote * 3, self.i)
        self.i += 3 if multi else 1
        if multi:
            self.newline()
        out = []
        while self.i < self.n:
            pos = self.i
            c = self.char()
            if c == quote:
                if not multi:
                    self.i += 1
                    return ''.join(out)
                if self.text.startswith(quote * 3, self.i):
                    self.i += 3
                    return ''.join(out)
                out.append(c)
                self.i += 1
                continue
            if c == '\n' or self.text.startswith('\r\n', self.i):
                if not multi:
                    self.error('newline in string found')
                self.newline()
                out.append('\n')
                continue
            if (ord(c) < 32 and c != '\t') or ord(c) == 127:
                self.error('invalid character in string: `%s`' % rust_char(c))
            self.i += 1
            if c == '\\' and quote == '"':
                if self.i >= self.n:
                    self.error('unterminated string', start)
                escaped = self.char()
                if multi and escaped in ' \t\r\n':
                    # Escaped line endings discard the following whitespace.
                    begin = self.i
                    while self.i < self.n and self.char() in ' \t':
                        self.i += 1
                    if not self.newline():
                        self.error('invalid escape character in string: `%s`' % rust_char(escaped), begin)
                    while self.i < self.n and self.char() in ' \t\r\n':
                        self.i += 1
                    continue
                self.i += 1
                escapes = {'b': '\b', 't': '\t', 'n': '\n', 'f': '\f', 'r': '\r', '"': '"', '\\': '\\'}
                if escaped in escapes:
                    out.append(escapes[escaped])
                elif escaped in 'uU':
                    count = 4 if escaped == 'u' else 8
                    digits = self.text[self.i:self.i + count]
                    if len(digits) != count or not re.fullmatch('[0-9a-fA-F]+', digits):
                        self.error('invalid hex escape code', self.i)
                    self.i += count
                    value = int(digits, 16)
                    if value > 0x10ffff or 0xd800 <= value <= 0xdfff:
                        self.error('invalid unicode escape code', pos)
                    out.append(chr(value))
                else:
                    self.error('invalid escape character in string: `%s`' % rust_char(escaped), self.i - 1)
            else:
                out.append(c)
        self.error('unterminated string', start)

    def key(self):
        c = self.char()
        if c in ('"', "'"):
            return self.string()
        match = re.match(r'[A-Za-z0-9_-]+', self.text[self.i:])
        if not match:
            self.error('expected a table key, found %s' % self.token_name())
        self.i += len(match.group())
        return match.group()

    def keys(self):
        result = [self.key()]
        self.space()
        while self.char() == '.':
            self.i += 1
            self.space()
            result.append(self.key())
            self.space()
        return result

    @staticmethod
    def value_kind(value):
        if isinstance(value, bool):
            return bool
        return type(value)

    def value(self):
        self.space()
        c = self.char()
        if not c:
            self.error('unexpected eof encountered')
        if c in ('"', "'"):
            return self.string()
        if c == '[':
            return self.array()
        if c == '{':
            return self.inline()
        start = self.i
        match = re.match(r'[^\s\],}#]+', self.text[self.i:])
        if not match:
            self.error('expected a value, found %s' % self.token_name())
        token = match.group()
        self.i += len(token)
        if token == 'true':
            return True
        if token == 'false':
            return False
        if re.match(r'^\d{4}-\d\d-\d\d', token) or re.match(r'^\d\d:\d\d:\d\d', token):
            return DateValue(token)
        number = token.replace('_', '')
        if re.fullmatch(r'[+-]?(?:inf|nan)', token):
            return float(number)
        int_pattern = r'[+-]?(?:0|[1-9](?:_?[0-9])*)'
        if re.fullmatch(int_pattern, token):
            value = int(number)
            if -(1 << 63) <= value < (1 << 63):
                return value
            self.error('invalid number', start)
        for prefix, digits, base in [('0x', '[0-9a-fA-F]', 16), ('0o', '[0-7]', 8), ('0b', '[01]', 2)]:
            if re.fullmatch(prefix + digits + '(?:_?' + digits + ')*', token):
                value = int(number[2:], base)
                if value < 1 << 63:
                    return value
                self.error('invalid number', start)
        float_pattern = r'[+-]?(?:0|[1-9](?:_?[0-9])*)(?:\.[0-9](?:_?[0-9])*)?(?:[eE][+-]?[0-9](?:_?[0-9])*)?'
        if ('.' in token or 'e' in token.lower()) and re.fullmatch(float_pattern, token):
            try:
                return float(number)
            except ValueError:
                pass
        self.error('invalid number', start)

    def array(self):
        self.i += 1
        values = []
        self.space(True)
        if self.char() == ']':
            self.i += 1
            return values
        while True:
            pos = self.i
            value = self.value()
            if values and self.value_kind(values[0]) is not self.value_kind(value):
                self.error('mixed types in an array', pos)
            values.append(value)
            self.space(True)
            if self.char() == ',':
                self.i += 1
                self.space(True)
                if self.char() == ']':
                    self.i += 1
                    return values
            else:
                self.expect(']', 'a right bracket')
                return values

    def inline(self):
        self.i += 1
        result = Table()
        self.space()
        if self.char() == '}':
            self.i += 1
            return result
        while True:
            keys = self.keys()
            self.expect('=', 'an equals')
            value = self.value()
            self.assign(result, keys, value)
            self.space()
            if self.char() == ',':
                self.i += 1
                self.space()
            else:
                self.expect('}', 'a right brace')
                return result

    def descend(self, table, key):
        child = table.get(key)
        if child is None:
            child = Table()
            table.put(key, child)
        if isinstance(child, list) and child and isinstance(child[-1], Table):
            child = child[-1]
        if not isinstance(child, Table):
            self.error('duplicate key: `%s`' % key)
        return child

    def assign(self, table, keys, value):
        for key in keys[:-1]:
            table = self.descend(table, key)
        table.put(keys[-1], value)

    def endline(self):
        self.space()
        if self.i >= self.n:
            return
        if not self.newline():
            self.error('expected newline, found %s' % self.token_name())

    def parse(self):
        while True:
            self.space(True)
            if self.i >= self.n:
                return self.root
            if self.char() == '[':
                start = self.i
                self.i += 1
                array = self.char() == '['
                if array:
                    self.i += 1
                self.space()
                keys = self.keys()
                self.expect(']', 'a right bracket')
                if array:
                    self.expect(']', 'a right bracket')
                table = self.root
                for key in keys[:-1]:
                    table = self.descend(table, key)
                key = keys[-1]
                path = tuple(keys)
                if array:
                    child = table.get(key)
                    if child is None:
                        child = []
                        table.put(key, child)
                    if not isinstance(child, list):
                        self.error('redefinition of table `%s` for key `%s`' % ('.'.join(keys), '.'.join(keys)), start)
                    new = Table()
                    child.append(new)
                    self.current = new
                else:
                    if path in self.defined:
                        self.error('redefinition of table `%s` for key `%s`' % ('.'.join(keys), '.'.join(keys)), start)
                    self.defined.add(path)
                    self.current = self.descend(table, key)
                self.endline()
            else:
                keys = self.keys()
                self.expect('=', 'an equals')
                value = self.value()
                self.assign(self.current, keys, value)
                self.endline()


def loads(text):
    return Parser(text).parse()


def basic_string(value, multiline=False):
    escapes = {'\b': '\\b', '\t': '\\t', '\n': '\\n', '\f': '\\f', '\r': '\\r', '"': '\\"', '\\': '\\\\'}
    chars = []
    for char in value:
        if char == '\n' and multiline:
            chars.append('\n')
        elif char in escapes:
            chars.append(escapes[char])
        elif ord(char) < 32:
            chars.append('\\u%04X' % ord(char))
        else:
            chars.append(char)
    if multiline:
        return '"""\n' + ''.join(chars) + '"""'
    return '"' + ''.join(chars) + '"'


def quote(value):
    multiline = '\n' in value
    literal = not any(ord(c) < 32 and c not in '\n\t' for c in value)
    literal = literal and "'''" not in value and not value.endswith("'")
    if literal:
        if multiline or "'" in value:
            return "'''" + ('\n' if multiline else '') + value + "'''"
        return "'" + value + "'"
    return basic_string(value, multiline)


def key_quote(key):
