"""Shared output, diagnostics, and string primitives."""
import os
import sys


class Failure(Exception):
    def __init__(self, message, code=1, raw=False):
        self.message = message
        self.code = code
        self.raw = raw


def fail(message):
    raise Failure(message)


def write_out(text):
    sys.stdout.write(text)
    sys.stdout.flush()


def os_error(exc):
    if isinstance(exc, UnicodeError):
        return 'stream did not contain valid UTF-8'
    if isinstance(exc, ValueError):
        return 'nul byte found in provided data'
    number = getattr(exc, 'errno', None)
    if number is None:
        return str(exc)
    return '%s (os error %s)' % (os.strerror(number), number)


def rust_char(char):
    specials = {'\0': '\\0', '\n': '\\n', '\r': '\\r', '\t': '\\t', "'": "\\'", '\\': '\\\\'}
    if char in specials:
        return specials[char]
    if not char.isprintable():
        return '\\u{%x}' % ord(char)
    return char


def rust_string(value):
    chars = []
    for c in value:
        if c == '"':
            chars.append('\\"')
        elif c == "'":
            chars.append(c)
        else:
            chars.append(rust_char(c))
    return '"' + ''.join(chars) + '"'


def panic(location, message):
    text = "thread 'main' panicked at %s:\n%s\n" % (location, message)
    text += 'note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n'
    raise Failure(text, 101, raw=True)
