                    child = table.get(key)
                    if child is None:
                        child = []
                        table.put(key, child)
                    if not isinstance(child, list):
                        self.error('redefinition of table `%s` for key `%s`' % ('.'.join(keys), '.'.join(keys)), start)
                    new = Table()
                    child.append(new)
                    self.current = new
                else:
                    if path in self.defined:
                        self.error('redefinition of table `%s` for key `%s`' % ('.'.join(keys), '.'.join(keys)), start)
                    self.defined.add(path)
                    self.current = self.descend(table, key)
                self.endline()
            else:
                keys = self.keys()
                self.expect('=', 'an equals')
                value = self.value()
                self.assign(self.current, keys, value)
                self.endline()


def loads(text):
    return Parser(text).parse()


def basic_string(value, multiline=False):
    escapes = {'\b': '\\b', '\t': '\\t', '\n': '\\n', '\f': '\\f', '\r': '\\r', '"': '\\"', '\\': '\\\\'}
    chars = []
    for char in value:
        if char == '\n' and multiline:
            chars.append('\n')
        elif char in escapes:
            chars.append(escapes[char])
        elif ord(char) < 32:
            chars.append('\\u%04X' % ord(char))
        else:
            chars.append(char)
