"""Configuration schema, discovery, and catalogue operations."""
import os
import pwd
from common import fail, os_error, rust_string
from toml_codec import Table, DateValue, TomlError, loads, dumps


def value_description(value):
    if isinstance(value, bool):
        return 'boolean `%s`' % str(value).lower()
    if isinstance(value, int):
        return 'integer `%d`' % value
    if isinstance(value, float):
        return 'floating point `%s`' % str(value)
    if isinstance(value, str):
        return 'string ' + rust_string(value)
    if isinstance(value, list):
        return 'sequence'
    return 'map'


def schema_error(message, path=''):
    if path:
        message += ' for key `%s`' % path
    raise TomlError(message)


def expect_type(value, expected, path):
    ok = {'a string': isinstance(value, str),
          'a sequence': isinstance(value, list),
          'map is expected': isinstance(value, Table),
          'struct Script': isinstance(value, Table),
          'struct ConfigDefaultOpts': isinstance(value, Table),
          'usize': isinstance(value, int) and not isinstance(value, bool)}.get(expected, False)
    if not ok:
        schema_error('invalid type: %s, expected %s' % (value_description(value), expected), path)
    if expected == 'usize' and value < 0:
        schema_error('invalid value: %s, expected usize' % value_description(value), path)
    return value


def string_list(value, path):
    expect_type(value, 'a sequence', path)
    for item in value:
        expect_type(item, 'a string', path)
    return value


def get_script(value, path, parent):
    if isinstance(value, list):
        for i, entry in enumerate(value[:4]):
            if i < 3:
                expect_type(entry, 'a string', parent)
            else:
                string_list(entry, parent)
        if len(value) != 4:
            schema_error('invalid length %s, expected struct Script with 4 elements' % len(value), parent)
        return {'command': value[0], 'description': value[1], 'tags': value[3]}
    expect_type(value, 'struct Script', path)
    result = {}
    for key, item in value.entries:
        if key not in ('command', 'description', 'tags'):
            continue
        if key in result:
            schema_error('duplicate field `%s`' % key, path)
        if key == 'tags':
            result[key] = string_list(item, path + '.' + key)
        else:
            result[key] = expect_type(item, 'a string', path + '.' + key)
    if 'command' not in result:
        schema_error('missing field `command`', path)
    return result


def get_defaults(value):
    if isinstance(value, list):
        if value:
            string_list(value[0], 'default')
        if len(value) > 1:
            expect_type(value[1], 'usize', 'default')
        if len(value) != 2:
            schema_error('invalid length %s, expected struct ConfigDefaultOpts with 2 elements' % len(value), 'default')
        return {'interpreter': value[0], 'command_width': value[1]}
    expect_type(value, 'struct ConfigDefaultOpts', 'default')
    result = {}
    for key, item in value.entries:
        if key not in ('interpreter', 'command_width'):
            continue
        if key in result:
            schema_error('duplicate field `%s`' % key, 'default')
        if key == 'interpreter':
            result[key] = string_list(item, 'default.' + key)
        else:
            result[key] = expect_type(item, 'usize', 'default.' + key)
    return result


def decode(text):
    root = loads(text)
    seen = set()
    scripts = {}
    defaults = {}
    for key, value in root.entries:
        if key not in ('scripts', 'default'):
            continue
        if key in seen:
            schema_error('duplicate field `%s`' % key)
        seen.add(key)
        if key == 'scripts':
            expect_type(value, 'map is expected', 'scripts')
            for alias, entry in value.entries:
                scripts[alias] = get_script(entry, 'scripts.' + alias, 'scripts')
        else:
            defaults = get_defaults(value)
    return scripts, defaults


def home_dir():
    return os.environ.get('HOME') or pwd.getpwuid(os.getuid()).pw_dir


def config_home():
    path = os.environ.get('XDG_CONFIG_HOME')
    if path and os.path.isabs(path):
        return path
    return os.path.join(home_dir(), '.config')


def discover(explicit, initializing=False):
    if explicit is not None:
        return explicit
    xdg = config_home()
    home = home_dir()
    paths = ['pier.toml', os.path.join(xdg, 'pier', 'config.toml'),
             os.path.join(xdg, 'pier', 'config'), os.path.join(xdg, 'pier.toml'),
             os.path.join(home, '.pier.toml'), os.path.join(home, '.pier')]
    for path in paths:
        if os.path.exists(path):
            return path
    if initializing:
        return paths[1]
    fail('No default config file found. See help for more info.')


class Catalog:
    def __init__(self, path, initialize=False):
        self.path = path
        self.scripts = {}
        self.defaults = {}
        if initialize:
            if os.path.exists(path):
                fail('Cannot initialize config at %s, file already exists.' % path)
            if path:
                stripped = path.rstrip('/')
                parent = os.path.dirname(stripped)
                if not os.path.exists(parent):
                    try:
                        os.mkdir(parent)
                    except OSError as exc:
                        fail('Failed to create directory. ' + os_error(exc))
        else:
            try:
                with open(path, 'rb') as config:
                    data = config.read().decode('utf-8')
            except (OSError, UnicodeError, ValueError) as exc:
                fail('Unable to read config from file %s: %s ' % (path, os_error(exc)))
            try:
                self.scripts, self.defaults = decode(data)
            except TomlError as exc:
                fail('Unable to parse toml config from file %s: %s' % (path, str(exc)))

    def save(self):
        data = dumps(self.scripts, self.defaults)
        try:
            with open(self.path, 'wb') as config:
                config.write(data.encode('utf-8'))
        except (OSError, UnicodeError, ValueError) as exc:
            fail('Unable to write config to %s: %s' % (self.path, os_error(exc)))

    def require(self, alias):
        if alias not in self.scripts:
            fail('AliasNotFound: No script found by alias ' + alias)
        return self.scripts[alias]

    def require_available(self, alias):
        if alias in self.scripts:
            fail('AliasAlreadyExists:  ' + alias)
