"""Unicode-aware, unwrapped four-column catalogue tables."""
import re
import unicodedata
from common import fail, panic


ANSI = re.compile(r'\x1b\[[0-?]*[ -/]*[@-~]')


def width(text):
    text = ANSI.sub('', text)
    result = 0
    for char in text:
        category = unicodedata.category(char)
        if category in ('Mn', 'Me', 'Cf', 'Cc', 'Cs'):
            continue
        result += 2 if unicodedata.east_asian_width(char) in ('F', 'W') else 1
    return result


def lines(text):
    if not text:
        return []
    result = text.split('\n')
    if result[-1] == '':
        result.pop()
    return [line[:-1] if line.endswith('\r') else line for line in result]


def truncate(command, limit):
    first = command.split('\n', 1)[0]
    if first.endswith('\r'):
        first = first[:-1]
    data = first.encode('utf-8')
    if len(data) <= limit:
        return first
    try:
        return data[:limit].decode('utf-8')
    except UnicodeDecodeError:
        begin = limit
        while begin > 0 and (data[begin] & 0xc0) == 0x80:
            begin -= 1
        end = begin + 1
        while end < len(data) and (data[end] & 0xc0) == 0x80:
            end += 1
        char = data[begin:end].decode('utf-8')
        panic('src/script.rs:36:52',
              "byte index %s is not a char boundary; it is inside '%s' (bytes %s..%s) of `%s`" %
              (limit, char, begin, end, first))


def table(rows, terminal=False):
    heading = ['Alias', 'Tags', 'Command', 'Description']
    content = [[lines(value) or [''] for value in row] for row in [heading] + rows]
    widths = [max(width(line) for row in content for line in row[col]) for col in range(4)]
    rule = '≖' * (sum(widths) + 13) + '\n'
    text = rule
    for row_index, row in enumerate(content):
        height = max(map(len, row))
        for i in range(height):
            values = [cell[i] if i < len(cell) else '' for cell in row]
            text += '⋮' + ''.join(' ' + value + ' ' * (widths[col] - width(value) + 1) + '⋮'
                                   for col, value in enumerate(values)) + '\n'
        if row_index == 0:
            text += rule
    return text + rule


def listing(catalog, options):
    if not catalog.scripts:
        fail('No scripts exist. Would you like to add a new script?')
    filtered = []
    for alias in sorted(catalog.scripts):
        script = catalog.scripts[alias]
        if 'tag' not in options:
            filtered.append((alias, script))
        else:
            for tag in options['tag']:
                if tag in script.get('tags', []):
                    filtered.append((alias, script))
    if options.get('list_aliases'):
        return ''.join(alias + '\n' for alias, script in filtered)
    limit = options.get('cmd_width', catalog.defaults.get('command_width', 80))
    full = options.get('cmd_full')
    rows = []
    for alias, script in filtered:
        command = script['command'] if full else truncate(script['command'], limit)
        rows.append([alias, ','.join(script.get('tags', [])), command, script.get('description', '')])
    return table(rows)
