    chars_a = [c for i, c in enumerate(first) if used_a[i]]
    chars_b = [c for i, c in enumerate(second) if used_b[i]]
    transpositions = sum(a != b for a, b in zip(chars_a, chars_b)) / 2
    score = (matched / len(first) + matched / len(second) + (matched - transpositions) / matched) / 3
    prefix = 0
    for a, b in zip(first[:4], second[:4]):
        if a != b:
            break
        prefix += 1
    if score > 0.7:
        score += prefix * .1 * (1 - score)
    return score


def suggest(word, choices):
    best = None
    score = .8
    for choice in choices:
        value = jaro_winkler(word, choice)
        if value > score:
            best, score = choice, value
    return best


class Arguments:
    def __init__(self, program, context='main'):
        self.program = program
        self.context = context
        self.specs = dict(GENERAL)
        self.specs.update(OPTIONS.get(context, {}))
        self.shorts = {spec[0]: key for key, spec in self.specs.items()}
        self.values = {}
        self.counts = {}
        self.order = []
        self.positions = []
        self.subcommand = None
        self.subargs = None
        self.terminated = False
        self.trailing = False

    def option_text(self, name):
        short, label, multi = self.specs[name]
        return '--' + name + ((' <' + label + '>' + ('...' if multi else '')) if label else '')

    def usage(self, extra=None):
        used = set(self.counts)
        if extra:
            used.add(extra)
        used -= {'help', 'version'}
        if self.context == 'add':
            used.discard('alias')
        if not used:
            return FULL_USAGE[self.context].format(program=self.program)
        parts = [self.program]
        if self.context != 'main':
            parts.append(self.context)
        parts += REQUIRED.get(self.context, [])
        parts += [self.option_text(key) for key in sorted(used)]
        return ' '.join(parts)

    def error(self, text, usage=None):
        if usage is None:
            usage = self.usage()
        raise Failure('error: ' + text + '\n\nUSAGE:\n    ' + usage + '\n\nFor more information try --help\n', raw=True)

    def unknown(self, token):
        text = "Found argument '%s' which wasn't expected, or isn't valid in this context" % token
        candidate = None
        if token.startswith('--'):
            candidate = suggest(token[2:].split('=', 1)[0], self.specs)
            if candidate:
                text += '\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m%s\x1b[0m?' % candidate
        self.error(text, self.usage(candidate))

    def subcommand_typo(self, word, candidate):
        text = "The subcommand '%s' wasn't recognized\n\tDid you mean '%s'?" % (word, candidate)
        text += "\n\nIf you believe you received this message in error, try re-running with '%s -- %s'" % (self.program, word)
        self.error(text)

    def help(self, long=False, context=None):
        context = context or self.context
        variant = 'long' if long and context != 'help' else 'short'
        name = 'help/%s_%s.txt' % (context, variant)
        text = pkgutil.get_data(__name__, name).decode('utf-8')
        text = text.replace('{program}', self.program).replace('{config_env}', os.environ.get('PIER_CONFIG_PATH', ''))
        write_out(text)
        raise SystemExit(0)

    def version(self):
        name = 'pier' if self.context == 'main' else self.program + '-' + self.context
        write_out(name + ' 0.1.6\n')
        raise SystemExit(0)

    def handle_help_subcommand(self, remaining):
        selected = 'main'
        for i, word in enumerate(remaining):
            if selected != 'main' or (word not in SUBCOMMANDS and word not in ALIASES):
                raise Failure("error: The subcommand '%s' wasn't recognized\n\nUSAGE:\n\t%s help <subcommands>...\n\nFor more information try --help\n" % (word, self.program), raw=True)
            selected = ALIASES.get(word, word)
        self.help(context=selected)

    @staticmethod
    def is_flag(word):
        return len(word) > 1 and word.startswith('-')

    def record(self, key, attached, args, index, long):
        if key == 'help':
            self.help(long)
        if key == 'version':
            self.version()
        self.counts[key] = self.counts.get(key, 0) + 1
        self.order.append(key)
        _, label, multi = self.specs[key]
        if label is None:
            self.values[key] = True
            return index
        values = []
        if attached is not None:
            values.append(attached)
        if not values or multi:
            while index < len(args) and not self.is_flag(args[index]):
                values.append(args[index])
                index += 1
                if not multi:
                    break
        if multi:
            self.values.setdefault(key, []).extend(values)
        else:
            self.values[key] = values[0] if values else None
        return index

    def parse(self, args):
        index = 0
        while index < len(args):
            word = args[index]
            index += 1
            if not self.terminated and not self.trailing:
                if word == '--':
                    self.terminated = True
                    continue
                if word.startswith('--'):
                    keyval = word[2:].split('=', 1)
                    name = keyval[0]
                    if name not in self.specs:
                        self.unknown(word.split('=', 1)[0])
                    attached = keyval[1] if len(keyval) == 2 else None
                    index = self.record(name, attached, args, index, True)
                    continue
                if self.is_flag(word):
                    group = word[1:]
                    j = 0
                    while j < len(group):
                        short = group[j]
                        j += 1
                        if short not in self.shorts:
                            self.unknown('-' + short)
                        name = self.shorts[short]
                        _, label, _ = self.specs[name]
                        attached = None
                        if label and j < len(group):
                            attached = group[j:]
                            if attached.startswith('='):
                                attached = attached[1:]
                            j = len(group)
                        index = self.record(name, attached, args, index, False)
                        if label:
                            break
                    continue
                if self.context == 'main' and (word in SUBCOMMANDS or word in ALIASES):
                    actual = ALIASES.get(word, word)
                    if actual == 'help':
                        self.handle_help_subcommand(args[index:])
                    self.subcommand = actual
                    self.subargs = Arguments(self.program, actual).parse(args[index:])
                    break
            if self.context == 'main' and not self.terminated:
                candidate = suggest(word, SUBCOMMANDS + list(ALIASES))
                if candidate:
                    self.subcommand_typo(word, candidate)
            places = POSITIONALS.get(self.context, [])
            variadic = self.context in ('main', 'run')
            if len(self.positions) >= len(places) and not variadic:
                self.unknown(word)
            if not places:
                self.unknown(word)
            self.positions.append(word)
            if self.context == 'main' and len(self.positions) >= 2:
                self.trailing = True
        if self.context == 'main' and 'config-file' not in self.values and 'PIER_CONFIG_PATH' in os.environ:
            self.values['config-file'] = os.environ['PIER_CONFIG_PATH']
            self.counts['config-file'] = 1
        self.validate()
        return self

    def validate(self):
        missing = []
        if self.context == 'add':
            if 'alias' not in self.values:
                missing = ['--alias <alias>']
        elif not self.subcommand:
            count = len(REQUIRED.get(self.context, []))
            missing = REQUIRED.get(self.context, [])[min(count, len(self.positions)):]
        if missing:
            self.error('The following required arguments were not provided:\n' + '\n'.join('    ' + value for value in missing))
        for key in self.order:
            if self.counts[key] > 1 and not self.specs[key][2]:
                self.error("The argument '%s' was provided more than once, but cannot be used multiple times" % self.option_text(key))
        for key in self.order:
            if self.specs[key][1] and not self.specs[key][2] and self.values[key] is None:
                self.error("The argument '%s' requires a value but none was supplied" % self.option_text(key))
        if 'cmd_width' in self.values:
            value = self.values['cmd_width']
            error = None
            if not value:
                error = 'cannot parse integer from empty string'
            elif not re.fullmatch(r'\+?[0-9]+', value):
                error = 'invalid digit found in string'
            elif int(value) > (1 << 64) - 1:
                error = 'number too large to fit in target type'
            if error:
                raise Failure("Invalid value for '--cmd_width <cmd-width>': " + error)
            self.values['cmd_width'] = int(value)
