"""Script catalogue command-line application."""
import os
import sys
from catalog import Catalog, discover
from cli import Arguments
from common import Failure, write_out
from display import listing
from runner import edit_text, execute


def main():
    program = os.path.basename(sys.argv[0])
    args = Arguments(program).parse(sys.argv[1:])
    action = args.subcommand or 'run'
    selected = args.subargs if args.subcommand else args
    opts = selected.values
    positions = selected.positions
    path = discover(args.values.get('config-file'), initializing=action == 'config-init')
    catalog = Catalog(path, initialize=action == 'config-init')
    if action == 'config-init':
        catalog.scripts['hello-pier'] = {
            'command': 'echo Hello, Pier!',
            'description': 'This is an example command.',
        }
        write_out('Added hello-pier\n')
        catalog.save()
    elif action == 'list':
        write_out(listing(catalog, opts))
    elif action == 'add':
        alias = opts['alias']
        command = positions[0] if positions else edit_text('')
        if not opts.get('force'):
            catalog.require_available(alias)
        script = {'command': command}
        if 'description' in opts:
            script['description'] = opts['description']
        if 'tag' in opts:
            script['tags'] = opts['tag']
        catalog.scripts[alias] = script
        write_out('Added ' + alias + '\n')
        catalog.save()
    elif action in ('copy', 'move'):
        source, target = positions
        script = catalog.require(source)
        if action == 'copy' or not opts.get('force'):
            catalog.require_available(target)
        if action == 'move':
            del catalog.scripts[source]
        catalog.scripts[target] = dict(script)
        write_out(action.capitalize() + ' from alias ' + source + ' to new alias ' + target + '\n')
        catalog.save()
    elif action == 'remove':
        alias = positions[0]
        catalog.require(alias)
        del catalog.scripts[alias]
        write_out('Removed ' + alias + '\n')
        catalog.save()
    elif action == 'edit':
        alias = positions[0]
        script = catalog.require(alias)
        script['command'] = edit_text(script['command'])
        write_out('Edited ' + alias + '\n')
        catalog.save()
    elif action == 'show':
        write_out(catalog.require(positions[0])['command'] + '\n')
    elif action == 'run':
        alias = positions[0]
        script = catalog.require(alias)
        return execute(alias, script, catalog.defaults, positions[1:], args.values.get('verbose', False))
    return 0


if __name__ == '__main__':
    try:
        sys.exit(main())
    except Failure as exc:
        sys.stderr.write(exc.message if exc.raw else 'error: ' + exc.message + '\n')
        sys.exit(exc.code)
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except OSError:
            pass
        sys.exit(1)
